mapper.select:
select e.*, c.name as className, s.name as subjectName, sem.name as semesterName
from exam e
left join class c on e.class_id = c.id
left join subject s on e.subject_id = s.id
left join semester sem on e.semester_id = sem.id
where 1=1

    and e.class_id = #{dto.classId}


    and e.subject_id = #{dto.subjectId}


    and e.semester_id = #{dto.semesterId}

order by e.id desc

SELECT e.id, c.name AS className, su.name AS subjectName, sem.name AS semesterName, e.exam_date AS examDate, e.exam_time AS examTime FROM exam e JOIN class c ON e.class_id = c.id JOIN subject su ON e.subject_id = su.id JOIN semester sem ON e.semester_id = sem.id
AND c.id = #{dto.classId} AND su.id = #{dto.subjectId} AND sem.id = #{dto.semesterId}
ORDER BY e.exam_date, c.id, su.id
